import{z as s,x as B,o as A,c as l,q as e,j as t,D as E,d as i,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"GDSII 与 OASIS","description":"","frontmatter":{"title":"GDSII 与 OASIS","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/gdsii-oasis.md","filePath":"litho/gdsii-oasis.md","lastUpdated":1791063341000}'),n={name:"litho/gdsii-oasis.md"};function I(D,a,d,p,h,m){const S=B("Mermaid");return A(),l("div",null,[a[2]||(a[2]=e('<h1 id="gdsii-与-oasis" tabindex="-1">GDSII 与 OASIS <a class="header-anchor" href="#gdsii-与-oasis" aria-label="Permalink to &quot;GDSII 与 OASIS&quot;">​</a></h1><div class="epigraph"><p>版图若不能无损、可核对、可压缩地交给掩模厂，后面的 MPC、写入和检验都在猜客户想印什么。</p><footer>—— 对照 SEMI P39 OASIS 与 Calma GDSII 流格式的产业通称</footer></div><p><a href="/litho/dtco-patterning">上一课</a>把设计规则、单元库与光刻分解收进同一张可行集，替计算光刻与掩模写入课程收尾。缺口是：晶圆侧再贵的光子，也要先变成一张可写的版。本课起一门新课——掩模制造与数据准备——从交换格式钉起。分层与布尔派生，留给<a href="/litho/layout-layers-flow">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设计库交出来的是多边形流，不是扫描机认的铬图。历史上的交换语言是 Calma GDSII：层号、数据类型、边界、路径、结构引用。它能表达几乎一切曼哈顿与折线多边形，但重复单元、曲线逼近和小 jog 会把文件胀到 TAPOUT 墙。SEMI P39 的 OASIS（Open Artwork System Interchange Standard）用更紧的重复记录、模态坐标和压缩，把同一套几何收成小一个数量级的流；面向写版的 OASIS.MASK（SEMI P44）再限制成掩模厂吃得下的子集。</p><p>缺口因此是<strong>交接口径</strong>，不是再讲一次 <a href="/litho/opc">OPC</a> 怎么挪边。把 GDSII 当「唯一真实」，会在曲线 ILT 上先撞磁盘与网络；把 OASIS 当「另一种画图软件」，会漏掉：校验和、模态计数与精确网格必须与合同里的数据库单位一致，否则后道 fracturing 在对另一张图。</p><h3 id="数据库单位不是显示精度" tabindex="-1">数据库单位不是显示精度 <a class="header-anchor" href="#数据库单位不是显示精度" aria-label="Permalink to &quot;数据库单位不是显示精度&quot;">​</a></h3><p>GDSII/OASIS 的坐标是整数网格。用户单位（微米）乘以数据库单位才是纳米级边。网格若粗于写模地址栅，OPC 碎边会先量化误差；网格若细到亚纳米却没有对应的写栅，只是把文件和 MRC 检查变慢。合同必须写清 DBU、精度与允许的几何类型（路径是否先展成边界、是否允许曲线记录）。</p><p><span class="marginnote">术语翻译：数据库单位（DBU）就是这张版图的「最小方格纸」。比如 1 DBU = 0.001 μm = 1 nm，所有顶点坐标都必须是它的整数倍——不是显示时的缩放，而是几何能否存在的硬约束。OPC 挪出来的 0.7 nm 碎边若不在网格上，先被吸到最近格点。</span></p><p><span class="marginnote">数字实例：一块存储阵列里同一种接触孔可能重复上亿次。GDSII 每个实例都要一条独立引用记录（几十字节起），仅此一项就能把流顶到 GB 量级；OASIS 只写一条 repetition 记录——原点、行列计数、间距——就把整个阵列说完了，这正是小一个数量级的来源。</span></p><p><span class="marginnote">OASIS 不是「压缩包里的 GDS」。它是另一种记录语法。比对必须在展开后的几何等价上做，不能比文件字节。</span></p>',11)),(A(),t(o,null,{default:E(()=>[r(S,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAME%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E7%89%88%E5%9B%BE%EF%BC%88%E5%A4%A7%E9%87%8F%E9%87%8D%E5%A4%8D%E5%8D%95%E5%85%83%EF%BC%89%22%5D%20--%3E%20GDS%5B%22GDSII%20%E8%AE%B0%E6%B3%95%EF%BC%9A%E6%AF%8F%E4%B8%AA%E5%AE%9E%E4%BE%8B%E5%90%84%E5%86%99%E4%B8%80%E6%9D%A1%E5%BC%95%E7%94%A8%22%5D%0A%20%20SAME%20--%3E%20OAS%5B%22OASIS%20%E8%AE%B0%E6%B3%95%EF%BC%9A%E4%B8%80%E6%9D%A1%20repetition%20%2B%20%E6%A8%A1%E6%80%81%E5%9D%90%E6%A0%87%22%5D%0A%20%20GDS%20--%3E%20BIG%5B%22%E9%87%8D%E5%A4%8D%E4%B8%8A%E4%B8%87%E6%AC%A1%E5%B0%B1%E5%86%99%E4%B8%8A%E4%B8%87%E6%9D%A1%20%E2%86%92%20%E6%96%87%E4%BB%B6%E8%83%80%E5%88%B0%20TAPOUT%20%E5%A2%99%22%5D%0A%20%20OAS%20--%3E%20SMALL%5B%22%E5%8F%AA%E5%86%99%E4%B8%80%E6%AC%A1%E5%8A%A0%E9%87%8D%E5%A4%8D%E8%AE%A1%E6%95%B0%20%E2%86%92%20%E5%B0%8F%E4%B8%80%E4%B8%AA%E6%95%B0%E9%87%8F%E7%BA%A7%22%5D%0A%20%20BIG%20--%3E%20PAIN%5B%22%E7%A3%81%E7%9B%98%20%2F%20%E7%BD%91%E7%BB%9C%20%2F%20MRC%20%E5%85%88%E8%A2%AB%E5%8E%8B%E5%9E%AE%22%5D%0A%20%20SMALL%20--%3E%20RISK%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%8A%B6%E6%80%81%E6%9C%BA%E9%94%99%E4%B8%80%E4%BD%8D%EF%BC%8C%E6%95%B4%E5%B1%82%E8%A7%A3%E7%A0%81%E9%94%99%E4%BD%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流的路径：设计 GDS/OASIS → 层映射与派生 → OPC/ILT 输出 → 掩模数据准备。每一跳都要能回答：多边形集合是否与上一跳等价（在约定公差内）。OASIS 的 repetition、ctrans 和 modal variables 是为了让标准单元阵列和 SRAM 不把同一多边形写一万遍；展开给 fracturing 时必须可逆核对。</p><p>曲线层若仍先折成微矩形再进 GDSII，文件与 <a href="/litho/curvilinear-mrc">曲线 MRC</a> 会一起炸。能走原生曲边或密折线的 OASIS 路径，才是后课数据量课的前提。本课只钉：格式选错，后面所有校正都在错误几何上算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GDSII 是顺序记录加结构层次；引用深度一深，流式工具必须建符号表。OASIS 把常用属性变成模态——下一条记录默认继承坐标与层——所以解码器状态机错一位，后面整层错位。这就是为什么掩模厂要官方校验器，而不是「能打开的浏览图」。</p><p><span class="marginnote">直觉类比：OASIS 的模态变量像聊天里的「同上」——下一句省略重复的上下文，省字省力，但必须按顺序逐句读；跳过或漏读一句，后面每一句都会接错。GDSII 则每句话把主谓宾写全，啰嗦但容错。</span></p><p>网格量化是第一种系统误差：边被吸到最近网格点，短 jog 消失或加倍。这与晶圆侧 MEF 无关，却会在写版 PEC 之前就已经改了频谱。后课默认：说到「客户数据」，先问是 GDSII 还是 OASIS、DBU 多少、是否 OASIS.MASK 子集。</p>',7)),(A(),t(o,null,{default:E(()=>[r(S,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20DES%5B%22%E8%AE%BE%E8%AE%A1%20GDS%20%2F%20OASIS%22%5D%20--%3E%20MAP%5B%22%E5%B1%82%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20OPC%5B%22OPC%20%2F%20ILT%20%E8%BE%93%E5%87%BA%22%5D%0A%20%20OPC%20--%3E%20MASK%5B%22OASIS.MASK%20%2F%20%E4%BD%9C%E4%B8%9A%E5%8D%95%22%5D%0A%20%20MASK%20--%3E%20FRAC%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%88%86%E5%89%B2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>格式不提高 NA，不缩短写入时间。它只决定几何能否无损到达 MDP。专利与加密包装（某些专有流）若不能在掩模厂展开核对，检验的 die-to-database 会失去金标准。不要发明「OASIS 比 GDS 一定准一个数量级」的 CD 数字——准的是语法与压缩，不是光刻分辨率。</p><p>后课默认读者已经知道：掩模链的输入是带网格的多边形流；层怎么变成一张版，下一课才拆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GDSII 是历史交换流；OASIS / OASIS.MASK 是为重复与掩模子集收紧的 SEMI 格式。</li><li>合同要写 DBU、几何类型与等价核对，不能只比文件大小。</li><li>曲线层不应先折成微矩形再进 GDSII，否则文件与 MRC 先炸。</li><li>出处：SEMI P39 OASIS；SEMI P44 OASIS.MASK；Calma GDSII 流惯例。</li></ul>',5))])}const _=s(n,[["render",I]]);export{O as __pageData,_ as default};
